/**
 * RowOutputInfo is used to describe the info of output columns returned by an operator.
 * It consists of a set of columnOutputInfo. Because of the Projection field in Operator,
 * an operator with a not null projection may take the original output of this operator
 * and project it to a new output.
 * <p>
 * To unify the output info of an operator, we use the RowOutputInfo to describe the output
 * row of this operator.
 * When an operator with a not null projection, the RowOutputInfo records the set of
 * columnOutputInfo of the projection.
 * When an operator without a not null projection, the RowOutInfo records the set of
 * columnOutputInfo of itself.
 */

public class RowOutputInfo {
private final Map<Integer, ColumnOutputInfo> columnOutputInfoMap;

public static RowOutputInfo createEmptyDescriptor() {
        return new RowOutputInfo();
    }

private RowOutputInfo() {
        this.columnOutputInfoMap = Maps.newHashMap();
    }

public RowOutputInfo(Collection<ColumnOutputInfo> columnEntries) {
        Map<Integer, ColumnOutputInfo> map = Maps.newHashMap();
        for (ColumnOutputInfo columnOutputInfo : columnEntries) {
            map.put(columnOutputInfo.getColId(), columnOutputInfo);
        }
        this.columnOutputInfoMap = map;
    }

public RowOutputInfo(Map<ColumnRefOperator, ScalarOperator> columnRefMap) {
        Map<Integer, ColumnOutputInfo> map = Maps.newHashMap();
        for (Map.Entry<ColumnRefOperator, ScalarOperator> entry : columnRefMap.entrySet()) {
            map.put(entry.getKey().getId(), new ColumnOutputInfo(entry));
        }
        this.columnOutputInfoMap = map;
    }
}

package org.opentripplanner.routing.fares.impl;

import java.time.ZoneOffset;

import java.util.List;

import java.util.stream.Collectors;

import org.opentripplanner.model.plan.Itinerary;

import org.opentripplanner.model.plan.Leg;

/**
 * Convert an OTP2 Itinerary to a list of Ride objects used by the fare calculators.
 */

public class RideMapper {
public static List<Ride> ridesForRaptorPath(Itinerary itinerary) {
        return itinerary.legs.stream()
                .filter(leg -> leg.isTransitLeg() || leg.flexibleTrip)
                .map(RideMapper::rideForTransitPathLeg)
                .collect(Collectors.toList());
    }

public static Ride rideForTransitPathLeg(Leg leg) {
        Ride ride = new Ride();
        ride.firstStop = leg.from.stop;
        ride.lastStop = leg.to.stop;

        ride.startZone = ride.firstStop.getFirstZoneAsString();
        ride.endZone = ride.lastStop.getFirstZoneAsString();

        // In almost all cases (except some loop routes) this should get the right set of zones passed through.
        // We don't have the position of the stops within the pattern so can't readily get more accurate than this.
        var zones = leg.intermediateStops.stream().map(stopArrival -> stopArrival.place.stop.getFirstZoneAsString()).collect(
                Collectors.toSet());
        ride.zones = zones;
        ride.agency = leg.getRoute().getAgency().getId();
        ride.route = leg.getRoute().getId();
        ride.trip = leg.getTrip().getId();

        // TODO verify that times are in seconds after midnight
        ride.startTime = leg.startTime.toInstant().atOffset(ZoneOffset.ofTotalSeconds(leg.agencyTimeZoneOffset)).toLocalTime().toSecondOfDay();
        ride.endTime = leg.startTime.toInstant().atOffset(ZoneOffset.ofTotalSeconds(leg.agencyTimeZoneOffset)).toLocalTime().toSecondOfDay();

        // In the default fare service, we classify rides by mode.
        ride.classifier = leg.mode;
        return ride;
    }
}

