public class Translate extends MatchingTask {
private String bundle;

private String bundleLanguage;

private String bundleCountry;

private String bundleVariant;

private File toDir;

private String srcEncoding;

private String destEncoding;

private String bundleEncoding;

private String startToken;

private String endToken;

private boolean forceOverwrite;

private Vector filesets = new Vector();

private Hashtable resourceMap = new Hashtable();

private FileUtils fileUtils = FileUtils.newFileUtils();

private long[] bundleLastModified = new long[7];

private long srcLastModified;

private long destLastModified;

private boolean loaded = false;

private void loadResourceMap(FileInputStream ins) throws BuildException {
        try {
            BufferedReader in = null;
            InputStreamReader isr = new InputStreamReader(ins, bundleEncoding);
            in = new BufferedReader(isr);
            String line = null;
            while ((line = in.readLine()) != null) {
                if (line.trim().length() > 1 && '#' != line.charAt(0) && '!' != line.charAt(0)) {
                    int sepIndex = line.indexOf('=');
                    if (-1 == sepIndex) {
                        sepIndex = line.indexOf(':');
                    }
                    if (-1 == sepIndex) {
                        for (int k = 0; k < line.length(); k++) {
                            if (Character.isSpaceChar(line.charAt(k))) {
                                sepIndex = k;
                                break;
                            }
                        }
                    }
                    if (-1 != sepIndex) {
                        String key = line.substring(0, sepIndex).trim();
                        String value = line.substring(sepIndex + 1).trim();
                        while (value.endsWith("\\")) {
                            value = value.substring(0, value.length() - 1);
                            if ((line = in.readLine()) != null) {
                                value = value + line.trim();
                            } else {
                                break;
                            }
                        }
                        if (key.length() > 0) {
                            if (resourceMap.get(key) == null) {
                                resourceMap.put(key, value);
                            }
                        }
                    }
                }
            }
            if (in != null) {
                in.close();
            }
        } catch (IOException ioe) {
            throw new BuildException(ioe.getMessage(), getLocation());
        }
    }

private void translate() throws BuildException {
        for (int i = 0; i < filesets.size(); i++) {
            FileSet fs = (FileSet) filesets.elementAt(i);
            DirectoryScanner ds = fs.getDirectoryScanner(getProject());
            String[] srcFiles = ds.getIncludedFiles();
            for (int j = 0; j < srcFiles.length; j++) {
                try {
                    File dest = fileUtils.resolveFile(toDir, srcFiles[j]);
                    try {
                        File destDir = new File(dest.getParent());
                        if (!destDir.exists()) {
                            destDir.mkdirs();
                        }
                    } catch (Exception e) {
                        log("Exception occured while trying to check/create " + " parent directory.  " + e.getMessage(), Project.MSG_DEBUG);
                    }
                    destLastModified = dest.lastModified();
                    File src = fileUtils.resolveFile(ds.getBasedir(), srcFiles[j]);
                    srcLastModified = src.lastModified();
                    if (forceOverwrite || destLastModified < srcLastModified || destLastModified < bundleLastModified[0] || destLastModified < bundleLastModified[1] || destLastModified < bundleLastModified[2] || destLastModified < bundleLastModified[3] || destLastModified < bundleLastModified[4] || destLastModified < bundleLastModified[5] || destLastModified < bundleLastModified[6]) {
                        log("Processing " + srcFiles[j], Project.MSG_DEBUG);
                        FileOutputStream fos = new FileOutputStream(dest);
                        BufferedWriter out = new BufferedWriter(new OutputStreamWriter(fos, destEncoding));
                        FileInputStream fis = new FileInputStream(src);
                        BufferedReader in = new BufferedReader(new InputStreamReader(fis, srcEncoding));
                        String line;
                        int stLength = startToken.length();
                        int etLength = endToken.length();
                        while ((line = in.readLine()) != null) {
                            int startIndex = -1;
                            int endIndex = -1;
                            outer: while (true) {
                                startIndex = line.indexOf(startToken, endIndex + etLength);
                                if (startIndex < 0 || startIndex + stLength >= line.length()) {
                                    break;
                                }
                                endIndex = line.indexOf(endToken, startIndex + stLength);
                                if (endIndex < 0) {
                                    break;
                                }
                                String matches = line.substring(startIndex + stLength, endIndex);
                                for (int k = 0; k < matches.length(); k++) {
                                    char c = matches.charAt(k);
                                    if (c == ':' || c == '=' || Character.isSpaceChar(c)) {
                                        endIndex = endIndex - 1;
                                        continue outer;
                                    }
                                }
                                String replace = null;
                                replace = (String) resourceMap.get(matches);
                                if (replace == null) {
                                    log("Warning: The key: " + matches + " hasn't been defined.", Project.MSG_DEBUG);
                                    replace = matches;
                                }
                                line = line.substring(0, startIndex) + replace + line.substring(endIndex + etLength);
                                endIndex = startIndex + replace.length() + etLength;
                                if (endIndex + etLength >= line.length()) {
                                    break;
                                }
                            }
                            out.write(line);
                            out.newLine();
                        }
                        if (in != null) {
                            in.close();
                        }
                        if (out != null) {
                            out.close();
                        }
                    } else {
                        log("Skipping " + srcFiles[j] + " as destination file is up to date", Project.MSG_VERBOSE);
                    }
                } catch (IOException ioe) {
                    throw new BuildException(ioe.getMessage(), getLocation());
                }
            }
        }
    }
}

