public class IvyClasspathContainerSerializer {
private static final String ROOT = "ivydecontainers";

private static final String IVYCP = "ivycp";

private static final String PATH = "path";

private static final String PROJECT = "project";

private static final String CPENTRIES = "cpentries";

private static final String CPATTRS = "cpattrs";

private static final String ATTR = "attr";

private static final String NAME = "name";

private static final String VALUE = "value";

private static final String CPENTRY = "cpentry";

private static final String KIND = "kind";

private static final String SOURCE = "source";

private static final String ACCESS_RULES = "accessRules";

private static final String RULE = "rule";

private static final String PATTERN = "pattern";

private File containersStateDir;

private IvyAttachementManager ivyAttachementManager;

public void save(IJavaProject project) {
        List ivycps = IvyClasspathUtil.getIvyClasspathContainers(project);
        try {
            FileOutputStream out = new FileOutputStream(new File(containersStateDir, project.getProject().getName() + ".xml"));
            try {
                write(out, ivycps);
            } finally {
                try {
                    out.close();
                } catch (IOException e) {
                }
            }
        } catch (Exception ioe) {
            IvyPlugin.log(IStatus.WARNING, "IvyDE container states of the project " + project.getProject().getName() + " cound not be saved", ioe);
        }
    }

public Map read(IJavaProject project) {
        try {
            FileInputStream in = new FileInputStream(new File(containersStateDir, project.getProject().getName() + ".xml"));
            try {
                return read(in);
            } finally {
                try {
                    in.close();
                } catch (IOException e) {
                }
            }
        } catch (Exception ioe) {
            IvyPlugin.log(IStatus.WARNING, "IvyDE container states of the project " + project.getProject().getName() + " cound not be read", ioe);
            return null;
        }
    }

private void write(OutputStream out, List containers) throws IOException {
        try {
            StreamResult result = new StreamResult(out);
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.newDocument();
            Node root = document.createElement(ROOT);
            document.appendChild(root);
            Iterator it = containers.iterator();
            while (it.hasNext()) {
                IvyClasspathContainer ivycp = (IvyClasspathContainer) it.next();
                Node node = document.createElement(IVYCP);
                root.appendChild(node);
                NamedNodeMap attributes = node.getAttributes();
                Attr attr = document.createAttribute(PATH);
                attr.setValue(ivycp.getPath().toString());
                attributes.setNamedItem(attr);
                attr = document.createAttribute(PROJECT);
                attr.setValue(ivycp.getConf().getProject().getName());
                attributes.setNamedItem(attr);
                writeCpEntries(ivycp, document, node, ivycp.getClasspathEntries());
                writeCpAttr(ivycp, document, node, ivycp.getConf().getAttributes());
            }
            Transformer transformer = TransformerFactory.newInstance().newTransformer();
            transformer.setOutputProperty(OutputKeys.METHOD, "xml");
            transformer.setOutputProperty(OutputKeys.ENCODING, "UTF-8");
            DOMSource source = new DOMSource(document);
            transformer.transform(source, result);
        } catch (ParserConfigurationException e) {
            throw new RuntimeException(e.getMessage(), e);
        } catch (TransformerException e) {
            if (e.getException() instanceof IOException) {
                throw (IOException) e.getException();
            }
            IOException ioe = new IOException(e.getMessage());
            ioe.initCause(e);
            throw ioe;
        }
    }

public Map read(InputStream in) throws IOException {
        try {
            InputSource source = new InputSource(in);
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder parser = factory.newDocumentBuilder();
            Document document = parser.parse(source);
            NodeList elements = document.getElementsByTagName(IVYCP);
            Map ivycps = new HashMap();
            int count = elements.getLength();
            for (int i = 0; i != count; i++) {
                Node node = elements.item(i);
                NamedNodeMap attributes = node.getAttributes();
                IPath path = new Path(getAttribute(attributes, PATH));
                IProject p = ResourcesPlugin.getWorkspace().getRoot().getProject(getAttribute(attributes, PROJECT));
                IJavaProject project = JavaCore.create(p);
                IClasspathEntry[] cpEntries = new IClasspathEntry[0];
                IClasspathAttribute[] cpAttributes = null;
                NodeList children = node.getChildNodes();
                for (int j = 0; j < children.getLength(); j++) {
                    Node item = children.item(j);
                    if (item.getNodeName().equals(CPENTRIES)) {
                        cpEntries = readCpEntries(item);
                    } else if (item.getNodeName().equals(CPATTRS)) {
                        cpAttributes = readCpAttr(item);
                    }
                }
                IvyClasspathContainer ivycp = new IvyClasspathContainer(project, path, cpEntries, cpAttributes);
                ivycps.put(path, ivycp);
            }
            return ivycps;
        } catch (ParserConfigurationException e) {
            throw new RuntimeException(e.getMessage(), e);
        } catch (SAXException e) {
            Throwable t = e.getCause();
            if (t instanceof IOException) {
                throw (IOException) t;
            }
            if (t == null) {
                t = e;
            }
            IOException ioe = new IOException(t.getMessage());
            ioe.initCause(t);
            throw ioe;
        }
    }
}

