package org.apache.tools.ant;

import java.beans.*;

import java.io.File;

import java.io.IOException;

import java.lang.reflect.*;

import java.util.*;

import org.xml.sax.SAXException;

import org.w3c.dom.*;

public class ProjectHelper {
private static void configureTasks(Project project, Target target, Element targetElement) throws BuildException {
        NodeList list = targetElement.getChildNodes();
        for (int i = 0; i < list.getLength(); i++) {
            Node node = list.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                String taskType = element.getTagName();
                if (!taskType.equals("target")) {
                    Task task = project.createTask(taskType);
                    NamedNodeMap nodeMap = element.getAttributes();
                    configureTask(project, task, nodeMap);
                    task.init();
                    task.setTarget(target);
                    target.addTask(task);
                }
            }
        }
    }

private static void configureTask(Project project, Task taskInst, NamedNodeMap nodeMap) throws BuildException {
        Object task = taskInst;
        if (task instanceof TaskAdapter)
            task = ((TaskAdapter) task).getProxy();
        Hashtable propertySetters = new Hashtable();
        BeanInfo beanInfo;
        try {
            beanInfo = Introspector.getBeanInfo(task.getClass());
        } catch (IntrospectionException ie) {
            String msg = "Can't introspect task class: " + task.getClass();
            throw new BuildException(msg);
        }
        PropertyDescriptor[] pda = beanInfo.getPropertyDescriptors();
        for (int i = 0; i < pda.length; i++) {
            PropertyDescriptor pd = pda[i];
            String property = pd.getName();
            Method setMethod = pd.getWriteMethod();
            if (setMethod != null) {
                Class[] ma = setMethod.getParameterTypes();
                if (ma.length == 1) {
                    Class c = ma[0];
                    if (c.getName().equals("java.lang.String")) {
                        propertySetters.put(property, setMethod);
                    }
                }
            }
        }
        for (int i = 0; i < nodeMap.getLength(); i++) {
            Node node = nodeMap.item(i);
            if (node.getNodeType() == Node.ATTRIBUTE_NODE) {
                Attr attr = (Attr) node;
                Method setMethod = (Method) propertySetters.get(attr.getName());
                if (setMethod == null) {
                    String msg = "Configuration property \"" + attr.getName() + "\" does not have a setMethod in " + task.getClass();
                    throw new BuildException(msg);
                }
                String value = replaceProperties(attr.getValue(), project.getProperties());
                try {
                    setMethod.invoke(task, new String[] { value });
                } catch (IllegalAccessException iae) {
                    String msg = "Error setting value for attrib: " + attr.getName();
                    iae.printStackTrace();
                    throw new BuildException(msg);
                } catch (InvocationTargetException ie) {
                    String msg = "Error setting value for attrib: " + attr.getName() + " in " + task.getClass().getName();
                    ie.printStackTrace();
                    ie.getTargetException().printStackTrace();
                    throw new BuildException(msg);
                }
            }
        }
    }

public static String replaceProperties(String value, Hashtable keys) throws BuildException {
        StringBuffer sb = new StringBuffer();
        int i = 0;
        int prev = 0;
        int pos;
        while ((pos = value.indexOf("$", prev)) >= 0) {
            if (pos > 0)
                sb.append(value.substring(prev, pos));
            if (value.charAt(pos + 1) != '{') {
                sb.append(value.charAt(pos + 1));
                prev = pos + 2;
            } else {
                int endName = value.indexOf('}', pos);
                if (endName < 0) {
                    throw new BuildException("Syntax error in prop: " + value);
                }
                String n = value.substring(pos + 2, endName);
                String v = (String) keys.get(n);
                sb.append(v);
                prev = endName + 1;
            }
        }
        if (prev < value.length())
            sb.append(value.substring(prev));
        return sb.toString();
    }
}

