@Path("types")
@Singleton
@Deprecated
public class TypesResource {
private static final Logger LOG = LoggerFactory.getLogger(TypesResource.class);

private static final Logger PERF_LOG = AtlasPerfTracer.getPerfLogger("rest.TypesResource");

private static AtlasTypeRegistry typeRegistry;

@Inject
    public TypesResource(AtlasTypeRegistry typeRegistry) {
        this.typeRegistry = typeRegistry;
    }

@Context
    private ResourceContext resourceContext;

@POST
    @Consumes({ Servlets.JSON_MEDIA_TYPE, MediaType.APPLICATION_JSON })
    @Produces(Servlets.JSON_MEDIA_TYPE)
    public Response submit(@Context HttpServletRequest request) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("==> TypesResource.submit()");
        }
        AtlasPerfTracer perf = null;
        if (AtlasPerfTracer.isPerfTraceEnabled(PERF_LOG)) {
            perf = AtlasPerfTracer.getPerfTracer(PERF_LOG, "TypesResource.submit()");
        }
        TypesREST typesRest = resourceContext.getResource(TypesREST.class);
        JSONArray typesResponse = new JSONArray();
        try {
            final String typeDefinition = Servlets.getRequestPayload(request);
            if (LOG.isDebugEnabled()) {
                LOG.debug("Creating type with definition {} ", typeDefinition);
            }
            AtlasTypesDef createTypesDef = TypeConverterUtil.toAtlasTypesDef(typeDefinition, typeRegistry);
            AtlasTypesDef createdTypesDef = typesRest.createAtlasTypeDefs(createTypesDef);
            List<String> typeNames = TypeConverterUtil.getTypeNames(createdTypesDef);
            for (int i = 0; i < typeNames.size(); i++) {
                final String name = typeNames.get(i);
                typesResponse.put(new JSONObject() {

                    {
                        put(AtlasClient.NAME, name);
                    }
                });
            }
            JSONObject response = new JSONObject();
            response.put(AtlasClient.REQUEST_ID, Servlets.getRequestId());
            response.put(AtlasClient.TYPES, typesResponse);
            return Response.status(ClientResponse.Status.CREATED).entity(response).build();
        } catch (AtlasBaseException e) {
            LOG.error("Type creation failed", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e));
        } catch (IllegalArgumentException e) {
            LOG.error("Unable to persist types", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e, Response.Status.BAD_REQUEST));
        } catch (WebApplicationException e) {
            LOG.error("Unable to persist types", e);
            throw e;
        } catch (Throwable e) {
            LOG.error("Unable to persist types", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e, Response.Status.INTERNAL_SERVER_ERROR));
        } finally {
            AtlasPerfTracer.log(perf);
            if (LOG.isDebugEnabled()) {
                LOG.debug("<== TypesResource.submit()");
            }
        }
    }

@PUT
    @Consumes({ Servlets.JSON_MEDIA_TYPE, MediaType.APPLICATION_JSON })
    @Produces(Servlets.JSON_MEDIA_TYPE)
    public Response update(@Context HttpServletRequest request) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("==> TypesResource.update()");
        }
        AtlasPerfTracer perf = null;
        if (AtlasPerfTracer.isPerfTraceEnabled(PERF_LOG)) {
            perf = AtlasPerfTracer.getPerfTracer(PERF_LOG, "TypesResource.update()");
        }
        TypesREST typesRest = resourceContext.getResource(TypesREST.class);
        JSONArray typesResponse = new JSONArray();
        try {
            final String typeDefinition = Servlets.getRequestPayload(request);
            if (LOG.isDebugEnabled()) {
                LOG.debug("Updating type with definition {} ", typeDefinition);
            }
            AtlasTypesDef updateTypesDef = TypeConverterUtil.toAtlasTypesDef(typeDefinition, typeRegistry);
            AtlasTypesDef updatedTypesDef = typesRest.updateAtlasTypeDefs(updateTypesDef);
            List<String> typeNames = TypeConverterUtil.getTypeNames(updatedTypesDef);
            for (int i = 0; i < typeNames.size(); i++) {
                final String name = typeNames.get(i);
                typesResponse.put(new JSONObject() {

                    {
                        put(AtlasClient.NAME, name);
                    }
                });
            }
            JSONObject response = new JSONObject();
            response.put(AtlasClient.REQUEST_ID, Servlets.getRequestId());
            response.put(AtlasClient.TYPES, typesResponse);
            return Response.ok().entity(response).build();
        } catch (AtlasBaseException e) {
            LOG.error("Unable to persist types", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e));
        } catch (IllegalArgumentException e) {
            LOG.error("Unable to persist types", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e, Response.Status.BAD_REQUEST));
        } catch (WebApplicationException e) {
            LOG.error("Unable to persist types", e);
            throw e;
        } catch (Throwable e) {
            LOG.error("Unable to persist types", e);
            throw new WebApplicationException(Servlets.getErrorResponse(e, Response.Status.INTERNAL_SERVER_ERROR));
        } finally {
            AtlasPerfTracer.log(perf);
            if (LOG.isDebugEnabled()) {
                LOG.debug("<== TypesResource.update()");
            }
        }
    }
}

package org.apache.hadoop.metrics2.sink.storm;

import backtype.storm.generated.ClusterSummary;

import backtype.storm.generated.SupervisorSummary;

import backtype.storm.generated.TopologySummary;

import backtype.storm.metric.IClusterReporter;

import backtype.storm.utils.NimbusClient;

import backtype.storm.utils.Utils;

import org.apache.commons.lang3.Validate;

import org.apache.hadoop.metrics2.sink.timeline.AbstractTimelineMetricsSink;

import org.apache.hadoop.metrics2.sink.timeline.TimelineMetric;

import org.apache.hadoop.metrics2.sink.timeline.TimelineMetrics;

import org.apache.hadoop.metrics2.sink.timeline.UnableToConnectException;

import java.net.InetAddress;

import java.net.UnknownHostException;

import java.util.ArrayList;

import java.util.List;

import java.util.Map;

public class StormTimelineMetricsReporter extends AbstractTimelineMetricsSink implements IClusterReporter {
public static final String METRICS_COLLECTOR_CATEGORY = "metrics_collector";

public static final String APP_ID = "appId";

private String hostname;

private String collectorUri;

private NimbusClient nimbusClient;

private String applicationId;

private int timeoutSeconds;

@Override
    protected int getTimeoutSeconds() {
        return timeoutSeconds;
    }

@Override
    public void prepare(Map conf) {
        LOG.info("Preparing Storm Metrics Reporter");
        try {
            try {
                hostname = InetAddress.getLocalHost().getHostName();
                if ((hostname == null) || (!hostname.contains("."))) {
                    hostname = InetAddress.getLocalHost().getCanonicalHostName();
                }
            } catch (UnknownHostException e) {
                LOG.error("Could not identify hostname.");
                throw new RuntimeException("Could not identify hostname.", e);
            }
            Validate.notNull(conf.get(METRICS_COLLECTOR_CATEGORY), METRICS_COLLECTOR_CATEGORY + " can not be null");
            Map cf = (Map) conf.get(METRICS_COLLECTOR_CATEGORY);
            Map stormConf = Utils.readStormConfig();
            this.nimbusClient = NimbusClient.getConfiguredClient(stormConf);
            String collector = cf.get(COLLECTOR_PROPERTY).toString();
            timeoutSeconds = cf.get(METRICS_POST_TIMEOUT_SECONDS) != null ? Integer.parseInt(cf.get(METRICS_POST_TIMEOUT_SECONDS).toString()) : DEFAULT_POST_TIMEOUT_SECONDS;
            applicationId = cf.get(APP_ID).toString();
            collectorUri = collector + WS_V1_TIMELINE_METRICS;
            if (collectorUri.toLowerCase().startsWith("https://")) {
                String trustStorePath = cf.get(SSL_KEYSTORE_PATH_PROPERTY).toString().trim();
                String trustStoreType = cf.get(SSL_KEYSTORE_TYPE_PROPERTY).toString().trim();
                String trustStorePwd = cf.get(SSL_KEYSTORE_PASSWORD_PROPERTY).toString().trim();
                loadTruststore(trustStorePath, trustStoreType, trustStorePwd);
            }
        } catch (Exception e) {
            LOG.warn("Could not initialize metrics collector, please specify " + "protocol, host, port under $STORM_HOME/conf/config.yaml ", e);
        }
    }

@Override
    public void reportMetrics() throws Exception {
        List<TimelineMetric> totalMetrics = new ArrayList<TimelineMetric>(7);
        ClusterSummary cs = this.nimbusClient.getClient().getClusterInfo();
        long currentTimeMillis = System.currentTimeMillis();
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Supervisors", String.valueOf(cs.get_supervisors_size())));
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Topologies", String.valueOf(cs.get_topologies_size())));
        List<SupervisorSummary> sups = cs.get_supervisors();
        int totalSlots = 0;
        int usedSlots = 0;
        for (SupervisorSummary ssum : sups) {
            totalSlots += ssum.get_num_workers();
            usedSlots += ssum.get_num_used_workers();
        }
        int freeSlots = totalSlots - usedSlots;
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Total Slots", String.valueOf(totalSlots)));
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Used Slots", String.valueOf(usedSlots)));
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Free Slots", String.valueOf(freeSlots)));
        List<TopologySummary> topos = cs.get_topologies();
        int totalExecutors = 0;
        int totalTasks = 0;
        for (TopologySummary topo : topos) {
            totalExecutors += topo.get_num_executors();
            totalTasks += topo.get_num_tasks();
        }
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Total Executors", String.valueOf(totalExecutors)));
        totalMetrics.add(createTimelineMetric(currentTimeMillis, applicationId, "Total Tasks", String.valueOf(totalTasks)));
        TimelineMetrics timelineMetrics = new TimelineMetrics();
        timelineMetrics.setMetrics(totalMetrics);
        try {
            emitMetrics(timelineMetrics);
        } catch (UnableToConnectException e) {
            LOG.warn("Unable to connect to Metrics Collector " + e.getConnectUrl() + ". " + e.getMessage());
        }
    }
}

package org.apache.ivy.ant;

import java.io.File;

