package org.apache.tools.ant.taskdefs;

import java.util.ArrayList;

import java.util.List;

import java.util.Iterator;

import java.util.Map;

import java.util.Set;

import java.util.HashSet;

import java.util.HashMap;

import java.util.Hashtable;

import java.util.Enumeration;

import org.apache.tools.ant.BuildException;

import org.apache.tools.ant.DynamicConfigurator;

import org.apache.tools.ant.ProjectHelper;

import org.apache.tools.ant.RuntimeConfigurable;

import org.apache.tools.ant.Target;

import org.apache.tools.ant.Task;

import org.apache.tools.ant.TaskContainer;

import org.apache.tools.ant.UnknownElement;

public class MacroInstance extends Task implements DynamicConfigurator {
private MacroDef macroDef;

private Map map = new HashMap();

private Map elements = new HashMap();

private Hashtable localProperties = new Hashtable();

public Object createDynamicElement(String name) throws BuildException {
        if (macroDef.getElements().get(name) == null) {
            throw new BuildException("unsupported element " + name);
        }
        if (elements.get(name) != null) {
            throw new BuildException("Element " + name + " already present");
        }
        Element ret = new Element();
        elements.put(name, ret);
        return ret;
    }

private String macroSubs(String s, Map macroMapping) {
        StringBuffer ret = new StringBuffer();
        StringBuffer macroName = new StringBuffer();
        boolean inMacro = false;
        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == '$') {
                inMacro = true;
            } else {
                if (inMacro) {
                    if (s.charAt(i) == '{') {
                        continue;
                    } else if (s.charAt(i) == '}') {
                        String name = macroName.toString();
                        String value = (String) macroMapping.get(name);
                        if (value == null) {
                            ret.append("${" + name + "}");
                        } else {
                            ret.append(value);
                        }
                        macroName = new StringBuffer();
                        inMacro = false;
                    } else {
                        macroName.append(s.charAt(i));
                    }
                } else {
                    ret.append(s.charAt(i));
                }
            }
        }
        return ret.toString();
    }

private UnknownElement copy(UnknownElement ue) {
        UnknownElement ret = new UnknownElement(ue.getTag());
        ret.setNamespace(ue.getNamespace());
        ret.setProject(getProject());
        ret.setQName(ue.getQName());
        ret.setTaskName(ue.getTaskName());
        ret.setLocation(ue.getLocation());
        if (getOwningTarget() == null) {
            Target t = new Target();
            t.setProject(getProject());
            ret.setOwningTarget(t);
        } else {
            ret.setOwningTarget(getOwningTarget());
        }
        RuntimeConfigurable rc = new RuntimeConfigurable(ret, ue.getTaskName());
        rc.setPolyType(ue.getWrapper().getPolyType());
        Map map = ue.getWrapper().getAttributeMap();
        for (Iterator i = map.entrySet().iterator(); i.hasNext(); ) {
            Map.Entry entry = (Map.Entry) i.next();
            rc.setAttribute((String) entry.getKey(), macroSubs((String) entry.getValue(), localProperties));
        }
        rc.addText(macroSubs(ue.getWrapper().getText().toString(), localProperties));
        Enumeration e = ue.getWrapper().getChildren();
        while (e.hasMoreElements()) {
            RuntimeConfigurable r = (RuntimeConfigurable) e.nextElement();
            UnknownElement unknownElement = (UnknownElement) r.getProxy();
            String tag = unknownElement.getTag();
            MacroDef.TemplateElement templateElement = (MacroDef.TemplateElement) macroDef.getElements().get(tag);
            if (templateElement == null) {
                UnknownElement child = copy(unknownElement);
                rc.addChild(child.getWrapper());
                ret.addChild(child);
            } else {
                Element element = (Element) elements.get(tag);
                if (element == null) {
                    if (!templateElement.isOptional()) {
                        throw new BuildException("Required nested element " + templateElement.getName() + " missing");
                    }
                    continue;
                }
                for (Iterator i = element.getUnknownElements().iterator(); i.hasNext(); ) {
                    UnknownElement child = (UnknownElement) i.next();
                    rc.addChild(child.getWrapper());
                    ret.addChild(child);
                }
            }
        }
        return ret;
    }
}

