import static org.osgi.service.http.whiteboard.HttpWhiteboardConstants.HTTP_WHITEBOARD_SERVLET_PATTERN;

public class CXFJaxRsBundleActivator implements BundleActivator {
private BundleContext _bundleContext;

private OSGiResult<?> _applicationsResult;

private OSGiResult<?> _singletonsResult;

private OSGiResult<?> _extensionsResult;

private OSGiResult<?> _applicationSingletonsResult;

private static OSGi<CXFJaxRsServiceRegistrator> cxfRegistrator(Bus bus, Application application, Map<String, Object> props) {
        CXFJaxRsServiceRegistrator registrator = new CXFJaxRsServiceRegistrator(bus, application, props);
        return onClose(registrator::close).then(register(CXFJaxRsServiceRegistrator.class, registrator, props).then(just(registrator)));
    }

@Override
    public void start(BundleContext bundleContext) throws Exception {
        _bundleContext = bundleContext;
        initRuntimeDelegate(bundleContext);
        Bus bus = BusFactory.newInstance(CXFBusFactory.class.getName()).createBus();
        registerCXFServletService(bus);
        OSGi<?> applications = serviceReferences(Application.class, getApplicationFilter()).flatMap(ref -> just(CXFJaxRsServiceRegistrator.getProperties(ref, JAX_RS_APPLICATION_BASE)).flatMap(properties -> service(ref).flatMap(application -> cxfRegistrator(bus, application, properties))));
        _applicationsResult = applications.run(bundleContext);
        Application defaultApplication = new Application() {
        };
        CXFJaxRsServiceRegistrator defaultServiceRegistrator = new CXFJaxRsServiceRegistrator(bus, defaultApplication, new HashMap<>());
        OSGi<?> singletons = serviceReferences(getSingletonsFilter()).flatMap(serviceReference -> waitForExtensionDependencies(serviceReference, just(CXFJaxRsServiceRegistrator.getProperties(serviceReference, JAX_RS_RESOURCE_BASE)).flatMap(properties -> service(serviceReference).flatMap(service -> safeRegisterEndpoint(serviceReference, defaultServiceRegistrator)))));
        _singletonsResult = singletons.run(bundleContext);
        OSGi<?> extensions = serviceReferences(getExtensionFilter()).flatMap(ref -> waitForExtensionDependencies(ref, safeRegisterExtension(ref, defaultServiceRegistrator)));
        _extensionsResult = extensions.run(bundleContext);
        OSGi<?> applicationSingletons = serviceReferences(format("(%s=*)", JAX_RS_APPLICATION_SELECT)).flatMap(ref -> just(ref.getProperty(JAX_RS_APPLICATION_SELECT).toString()).flatMap(applicationFilter -> services(CXFJaxRsServiceRegistrator.class, applicationFilter).flatMap(registrator -> testProvider(ref).flatMap(isProvider -> {
            if (isProvider) {
                return safeRegisterExtension(ref, registrator);
            } else {
                return safeRegisterEndpoint(ref, registrator);
            }
        }))));
        _applicationSingletonsResult = applicationSingletons.run(bundleContext);
    }

private OSGi<Boolean> testProvider(ServiceReference<?> serviceReference) {
        return bundleContext().flatMap(bundleContext -> {
            Object service = bundleContext.getService(serviceReference);
            Class<?> serviceClass = service.getClass();
            if (serviceClass.isAnnotationPresent(Provider.class)) {
                return just(Boolean.TRUE);
            } else {
                return just(Boolean.FALSE);
            }
        });
    }

@Override
    public void stop(BundleContext context) throws Exception {
        _applicationSingletonsResult.close();
        _applicationsResult.close();
        _extensionsResult.close();
        _singletonsResult.close();
    }
}

