        } else if (proc.equals("xslp")) {
            log("DEPRECATED - xslp processor is deprecated. Use trax " + "instead.");
            final Class clazz = loadClass(XSLP_LIAISON_CLASS);
            liaison = (XSLTLiaison) clazz.newInstance();
