package org.apache.activemq.broker.region.virtual;

import java.util.Collection;

import java.util.Iterator;

import org.apache.activemq.broker.ProducerBrokerExchange;

import org.apache.activemq.broker.region.Destination;

import org.apache.activemq.broker.region.DestinationFilter;

import org.apache.activemq.command.ActiveMQDestination;

import org.apache.activemq.command.Message;

import org.apache.activemq.filter.MessageEvaluationContext;

public class CompositeDestinationInterceptor extends DestinationFilter {

    private Collection forwardDestinations;

    private boolean forwardOnly;

    private boolean copyMessage;

    public CompositeDestinationInterceptor(Destination next, Collection forwardDestinations, boolean forwardOnly, boolean copyMessage) {
        super(next);
        this.forwardDestinations = forwardDestinations;
        this.forwardOnly = forwardOnly;
        this.copyMessage = copyMessage;
    }

    public void send(ProducerBrokerExchange context, Message message) throws Exception {
        MessageEvaluationContext messageContext = null;
        for (Iterator iter = forwardDestinations.iterator(); iter.hasNext(); ) {
            ActiveMQDestination destination = null;
            Object value = iter.next();
            if (value instanceof FilteredDestination) {
                FilteredDestination filteredDestination = (FilteredDestination) value;
                if (messageContext == null) {
                    messageContext = new MessageEvaluationContext();
                    messageContext.setMessageReference(message);
                }
                messageContext.setDestination(filteredDestination.getDestination());
                if (filteredDestination.matches(messageContext)) {
                    destination = filteredDestination.getDestination();
                }
            } else if (value instanceof ActiveMQDestination) {
                destination = (ActiveMQDestination) value;
            }
            if (destination == null) {
                continue;
            }
            if (copyMessage) {
                message = message.copy();
                message.setDestination(destination);
            }
            send(context, message, destination);
        }
        if (!forwardOnly) {
            super.send(context, message);
        }
    }
}

package com.malhartech.stream;

import com.malhartech.api.Sink;

import com.malhartech.api.StreamCodec;

import com.malhartech.api.StreamCodec.DataStatePair;

import com.malhartech.bufferserver.client.Subscriber;

import com.malhartech.engine.*;

import java.lang.reflect.Array;

import java.util.HashMap;

import org.slf4j.Logger;

import org.slf4j.LoggerFactory;

public class BufferServerInputStream extends Subscriber implements Stream<Object> {

    private final HashMap<String, Sink<Object>> outputs = new HashMap<String, Sink<Object>>();

    private long baseSeconds;

    private int lastWindowId = WindowGenerator.MAX_WINDOW_ID;

    @SuppressWarnings("VolatileArrayField")
    private volatile Sink<Object>[] sinks = NO_SINKS;

    private StreamCodec<Object> serde;

    DataStatePair dsp = new DataStatePair();

    public BufferServerInputStream(String id) {
        super(id);
    }

    @Override
    public void activate(StreamContext context) {
        logger.debug("registering subscriber: id={} upstreamId={} streamLogicalName={} windowId={} mask={} partitions={} server={}", new Object[] { context.getSinkId(), context.getSourceId(), context.getId(), context.getStartingWindowId(), context.getPartitionMask(), context.getPartitions(), context.getBufferServerAddress() });
        baseSeconds = context.getStartingWindowId() & 0xffffffff00000000L;
        serde = context.attr(StreamContext.CODEC).get();
        activateSinks();
        activate(context.getId() + '/' + context.getSinkId(), context.getSourceId(), context.getPartitionMask(), context.getPartitions(), context.getStartingWindowId());
    }

    @Override
    public void onMessage(byte[] buffer, int offset, int size) {
        com.malhartech.bufferserver.packet.Tuple data = com.malhartech.bufferserver.packet.Tuple.getTuple(buffer, offset, size);
        Tuple t;
        switch(data.getType()) {
            case CHECKPOINT:
                serde.resetState();
                return;
            case CODEC_STATE:
                dsp.state = data.getData();
                return;
            case PAYLOAD:
                dsp.data = data.getData();
                Object o = serde.fromByteArray(dsp);
                for (Sink<Object> s : sinks) {
                    s.process(o);
                }
                return;
            case END_WINDOW:
                t = new EndWindowTuple();
                t.setWindowId(baseSeconds | (lastWindowId = data.getWindowId()));
                break;
            case END_STREAM:
                t = new EndStreamTuple();
                t.setWindowId(baseSeconds | data.getWindowId());
                break;
            case RESET_WINDOW:
                baseSeconds = (long) data.getBaseSeconds() << 32;
                if (lastWindowId < WindowGenerator.MAX_WINDOW_ID) {
                    return;
                }
                t = new ResetWindowTuple();
                t.setWindowId(baseSeconds | data.getWindowWidth());
                break;
            case BEGIN_WINDOW:
                t = new Tuple(data.getType());
                t.setWindowId(baseSeconds | data.getWindowId());
                break;
            default:
                throw new IllegalArgumentException("Unhandled Message Type " + data.getType());
        }
        for (int i = sinks.length; i-- > 0; ) {
            sinks[i].process(t);
        }
    }

    @Override
    @SuppressWarnings("unchecked")
    public void setSink(String id, Sink<Object> sink) {
        if (sink == null) {
            outputs.remove(id);
            if (outputs.isEmpty()) {
                sinks = NO_SINKS;
            }
        } else {
            outputs.put(id, (Sink) sink);
            if (sinks != NO_SINKS) {
                activateSinks();
            }
        }
    }

    @Override
    public boolean isMultiSinkCapable() {
        return true;
    }

    private void activateSinks() {
        logger.debug("activating sinks = {} on {}", outputs);
        @SuppressWarnings("unchecked")
        Sink<Object>[] newSinks = (Sink<Object>[]) Array.newInstance(Sink.class, outputs.size());
        int i = 0;
        for (final Sink<Object> s : outputs.values()) {
            newSinks[i++] = s;
        }
        sinks = newSinks;
    }

    @Override
    public void process(Object tuple) {
        throw new IllegalAccessError("Attempt to pass payload " + tuple + " to " + this + " from source other than buffer server!");
    }

    @Override
    public void setup(StreamContext context) {
        super.setup(context.getBufferServerAddress(), context.attr(StreamContext.EVENT_LOOP).get());
    }

    private static final Logger logger = LoggerFactory.getLogger(BufferServerInputStream.class);
}

package com.malhartech.dag;

import com.malhartech.annotation.PortAnnotation;

import com.malhartech.util.CircularBuffer;

import java.util.HashMap;

import java.util.Map.Entry;

import org.slf4j.Logger;

import org.slf4j.LoggerFactory;

public abstract class AbstractSynchronousInputModule extends AbstractInputModule implements Runnable {

    private static final Logger logger = LoggerFactory.getLogger(AbstractSynchronousInputModule.class);

    protected transient HashMap<String, CircularBuffer<Object>> handoverBuffers = new HashMap<String, CircularBuffer<Object>>();

    protected transient Thread syncThread;

    @Override
    @SuppressWarnings("SleepWhileInLoop")
    public void connected(String id, Sink dagpart) {
        PortAnnotation port = getPort(id);
        if (port != null && (port.type() == PortAnnotation.PortType.OUTPUT || port.type() == PortAnnotation.PortType.BIDI)) {
            CircularBuffer<?> cb = handoverBuffers.get(port.name());
            if (dagpart == null) {
                if (cb != null) {
                    try {
                        while (cb.size() > 0) {
                            Thread.sleep(spinMillis);
                        }
                    } catch (InterruptedException ie) {
                        logger.info("{} aborting handing over messages downstream due to interrupt", this);
                    }
                }
            } else if (cb == null) {
                handoverBuffers.put(port.name(), new CircularBuffer<Object>(bufferCapacity));
            }
        }
    }

    @Override
    public void activated(ModuleContext context) {
        syncThread = new Thread(this, this + "-sync");
        syncThread.start();
    }

    @Override
    public void deactivated(ModuleContext context) {
        syncThread.interrupt();
        syncThread = null;
    }

    @Override
    @SuppressWarnings("SleepWhileInLoop")
    public void emit(Object payload) {
        try {
            for (CircularBuffer<Object> cb : handoverBuffers.values()) {
                cb.put(payload);
            }
        } catch (InterruptedException ex) {
            logger.warn("{} aborting emit as got interrupted while writing {}", this, payload);
        }
    }

    @Override
    public void emit(String id, Object payload) {
        CircularBuffer<Object> cb = handoverBuffers.get(id);
        if (cb != null) {
            try {
                cb.put(payload);
            } catch (InterruptedException ex) {
                logger.warn("{} aborting emit as got interrupted while writing {}", this, payload);
            }
        }
    }

    @Override
    final public void process(Object payload) {
        for (Entry<String, CircularBuffer<Object>> e : handoverBuffers.entrySet()) {
            Sink s = outputs.get(e.getKey());
            CircularBuffer<?> cb = e.getValue();
            for (int i = cb.size(); i-- > 0; ) {
                s.process(cb.poll());
            }
        }
    }
}

