import org.apache.avalon.DefaultComponentManager;

import org.apache.avalon.Disposable;

import org.apache.avalon.Initializable;

import org.apache.avalon.camelot.Deployer;

import org.apache.avalon.camelot.DeploymentException;

import org.apache.avalon.camelot.RegistryException;

import org.apache.log.Logger;

public class DefaultProjectEngine implements ProjectEngine, Initializable, Disposable {
protected Deployer m_deployer;

protected TaskletRegistry m_taskletRegistry;

protected ConverterRegistry m_converterRegistry;

protected TaskletEngine m_taskletEngine;

protected Logger m_logger;

protected ProjectListenerSupport m_listenerSupport;

protected DefaultComponentManager m_componentManager;

protected void executeTargetWork(final String name, final Target target, final TaskletContext context) {
        m_logger.debug("Executing target " + name);
        final Iterator tasks = target.getTasks();
        while (tasks.hasNext()) {
            final Configuration task = (Configuration) tasks.next();
            executeTask(task, context);
        }
    }

protected void executeTask(final Configuration configuration, final TaskletContext context) throws AntException {
        final String name = configuration.getName();
        m_logger.debug("Executing task " + name);
        final TaskletContext taskletContext = context;
        taskletContext.setProperty(TaskletContext.NAME, name);
        m_taskletEngine.contextualize(taskletContext);
        m_listenerSupport.taskletStarted(name);
        m_taskletEngine.execute(configuration);
        m_listenerSupport.taskletFinished();
    }
}

package org.apache.tools.ant.taskdefs.optional.dotnet;

import java.io.File;

import java.util.Vector;

import java.util.Iterator;

import org.apache.tools.ant.BuildException;

import org.apache.tools.ant.Task;

import org.apache.tools.ant.taskdefs.condition.Os;

import org.apache.tools.ant.util.FileUtils;

public class WsdlToDotnet extends Task {
private File destFile = null;

private String url = null;

private String srcFileName = null;

private String language = "CS";

private boolean server = false;

private String namespace = null;

private boolean failOnError = true;

protected String extraOptions = null;

private boolean isMono = !Os.isFamily("windows");

private String protocol = null;

private boolean parseableErrors = false;

private Vector schemas = new Vector();

protected void validate() throws BuildException {
        if (destFile == null) {
            throw new BuildException("destination file must be specified");
        }
        if (destFile.isDirectory()) {
            throw new BuildException("destination file is a directory");
        }
        if (url != null && srcFileName != null) {
            throw new BuildException("you can not specify both a source file and a URL");
        }
        if (url == null && srcFileName == null) {
            throw new BuildException("you must specify either a source file or a URL");
        }
        if (srcFileName != null) {
            File srcFile = getProject().resolveFile(srcFileName);
            if (!srcFile.exists()) {
                throw new BuildException("source file does not exist");
            }
            if (srcFile.isDirectory()) {
                throw new BuildException("source file is a directory");
            }
        }
    }

public void execute() throws BuildException {
        validate();
        NetCommand command = new NetCommand(this, "WSDL", "wsdl");
        command.setFailOnError(failOnError);
        command.addArgument("/nologo");
        command.addArgument("/out:" + destFile);
        command.addArgument("/language:", language);
        if (server) {
            command.addArgument("/server");
        }
        command.addArgument("/namespace:", namespace);
        if (protocol != null) {
            command.addArgument("/protocol:" + protocol);
        }
        if (parseableErrors) {
            command.addArgument("/parsableErrors");
        }
        command.addArgument(extraOptions);
        boolean rebuild = true;
        long destLastModified = -1;
        if (srcFileName != null) {
            File srcFile = getProject().resolveFile(srcFileName);
            if (isMono) {
                command.addArgument(srcFileName);
            } else {
                command.addArgument(srcFile.toString());
            }
            if (destFile.exists()) {
                destLastModified = destFile.lastModified();
            }
            if (srcFile.exists() && srcFile.lastModified() <= destLastModified) {
                rebuild = false;
            }
        } else {
            rebuild = true;
            command.addArgument(url);
        }
        Iterator it = schemas.iterator();
        while (it.hasNext()) {
            Schema schema = (Schema) it.next();
            long schemaTimestamp;
            schemaTimestamp = schema.getTimestamp();
            if (schemaTimestamp > destLastModified) {
                rebuild = true;
            }
            command.addArgument(schema.evaluate());
        }
        if (rebuild) {
            command.runCommand();
        }
    }
}

package com.malhartech.dag;

import com.malhartech.annotation.ModuleAnnotation;

import com.malhartech.annotation.PortAnnotation;

import java.util.HashMap;

import org.slf4j.Logger;

import org.slf4j.LoggerFactory;

public abstract class AbstractBaseModule implements Operator {

    private static final Logger logger = LoggerFactory.getLogger(AbstractBaseModule.class);

    protected transient String id;

    protected final transient HashMap<String, Sink> outputs = new HashMap<String, Sink>();

    protected transient int spinMillis = 10;

    protected transient int bufferCapacity = 1024 * 1024;

    protected transient int processedTupleCount;

    protected transient int generatedTupleCount;

    @SuppressWarnings(value = "VolatileArrayField")
    protected volatile transient Sink[] sinks = Sink.NO_SINKS;

    protected transient boolean alive;

    protected PortAnnotation getPort(String id) {
        Class<? extends Operator> clazz = this.getClass();
        ModuleAnnotation na = clazz.getAnnotation(ModuleAnnotation.class);
        if (na != null) {
            PortAnnotation[] ports = na.ports();
            for (PortAnnotation pa : ports) {
                if (id.equals(pa.name())) {
                    return pa;
                }
            }
        }
        return null;
    }

    @SuppressWarnings("SillyAssignment")
    protected void activateSinks() {
        sinks = new Sink[outputs.size()];
        int i = 0;
        for (Sink s : outputs.values()) {
            sinks[i++] = s;
        }
        sinks = sinks;
    }

    public void deactivateSinks() {
        sinks = Sink.NO_SINKS;
        outputs.clear();
    }

    @Override
    public final void deactivate() {
        alive = false;
    }

    @Override
    public void beginWindow() {
    }

    public void connected(String id, Sink dagpart) {
    }

    public void activated(ModuleContext context) {
    }

    public void deactivated(ModuleContext context) {
    }

    public void emit(final Object payload) {
        for (int i = sinks.length; i-- > 0; ) {
            sinks[i].process(payload);
        }
        generatedTupleCount++;
    }

    public void emit(String id, Object payload) {
        final Sink s = outputs.get(id);
        outputs.get(id).process(payload);
        generatedTupleCount++;
    }

    @Override
    public void endWindow() {
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == null) {
            return false;
        }
        if (getClass() != obj.getClass()) {
            return false;
        }
        final AbstractBaseModule other = (AbstractBaseModule) obj;
        if ((this.id == null) ? (other.id != null) : !this.id.equals(other.id)) {
            return false;
        }
        return true;
    }

    public int getBufferCapacity() {
        return bufferCapacity;
    }

    public String getId() {
        return id;
    }

    public int getSpinMillis() {
        return spinMillis;
    }

    @Override
    public int hashCode() {
        return id == null ? super.hashCode() : id.hashCode();
    }

    public void setBufferCapacity(int bufferCapacity) {
        this.bufferCapacity = bufferCapacity;
    }

    public void setId(String id) {
        this.id = id;
    }

    public void setSpinMillis(int spinMillis) {
        this.spinMillis = spinMillis;
    }

    @Override
    public void setup(ModuleConfiguration config) throws FailedOperationException {
    }

    @Override
    public void teardown() {
    }

    @Override
    public String toString() {
        return this.getClass().getSimpleName() + "{id=" + id + '}';
    }

    public int getProcessedTupleCount() {
        return processedTupleCount;
    }

    protected void emitEndStream() {
        logger.debug("{} sending EndOfStream", this);
        EndStreamTuple est = new EndStreamTuple();
        for (final Sink output : outputs.values()) {
            output.process(est);
        }
    }
}

import org.apache.tools.ant.Task;

import org.apache.tools.ant.BuildException;

import org.apache.tools.ant.types.FileSet;

import org.apache.tools.ant.DirectoryScanner;

import java.util.ArrayList;

import java.util.List;

import java.io.File;

public class Find extends Task {
private String file;

private String location;

private List<FileSet> filesets = new ArrayList<>();

protected void validate() {
        if (file == null)
            throw new BuildException("file not set");
        if (location == null)
            throw new BuildException("location not set");
        if (filesets.size() < 1)
            throw new BuildException("fileset not set");
    }

public void execute2() {
        validate();
        String foundLocation = null;
        for (FileSet fs : filesets) {
            DirectoryScanner ds = fs.getDirectoryScanner(getProject());
            String[] includedFiles = ds.getIncludedFiles();
            for (String includedFile : includedFiles) {
                String filename = includedFile.replace('\\', '/');
                filename = filename.substring(filename.lastIndexOf("/") + 1);
                if (foundLocation == null && file.equals(filename)) {
                    File base = ds.getBasedir();
                    File found = new File(base, includedFile);
                    foundLocation = found.getAbsolutePath();
                }
            }
        }
        if (foundLocation != null)
            getProject().setNewProperty(location, foundLocation);
    }
}

package org.apache.tools.ant.taskdefs.optional.repository;

import org.apache.tools.ant.BuildException;

import org.apache.tools.ant.Project;

import org.apache.tools.ant.Task;

import org.apache.tools.ant.types.Reference;

import java.io.File;

import java.io.IOException;

import java.util.Iterator;

import java.util.LinkedList;

import java.util.List;

public class GetLibraries extends Task {
private File destDir;

private boolean forceDownload = false;

private boolean offline = false;

private List libraries = new LinkedList();

private Repository repository;

public static final String ERROR_ONE_REPOSITORY_ONLY = "Only one repository is allowed";

public static final String ERROR_NO_DEST_DIR = "No destination directory";

public static final String ERROR_NO_REPOSITORY = "No repository defined";

public static final String ERROR_NO_LIBRARIES = "No libraries to load";

public static final String ERROR_REPO_PROBE_FAILED = "repository probe failed with ";

public static final String ERROR_LIBRARY_FETCH_FAILED = "failed to retrieve ";

public static final String ERROR_FORCED_DOWNLOAD_FAILED = "Failed to download every file on a forced download";

public static final String ERROR_INCOMPLETE_RETRIEVAL = "Not all libraries could be retrieved";

public void validate() {
        if (destDir == null || !destDir.exists() || !destDir.isDirectory()) {
            throw new BuildException(ERROR_NO_DEST_DIR);
        }
        if (repository == null) {
            throw new BuildException(ERROR_NO_REPOSITORY);
        }
        Iterator it = libraries.iterator();
        while (it.hasNext()) {
            Library library = (Library) it.next();
            library.validate();
        }
    }

public void execute() throws BuildException {
        validate();
        Repository repo = repository.resolve();
        repo.validate();
        int toFetch = libraries.size();
        if (toFetch == 0) {
            throw new BuildException(ERROR_NO_LIBRARIES);
        }
        int fetched = 0;
        log("Getting libraries from " + repo.toString(), Project.MSG_VERBOSE);
        log("Saving libraries to " + destDir.toString(), Project.MSG_VERBOSE);
        bindAllLibraries();
        if (isOffline()) {
            log("No retrieval, task is \"offline\"");
            verifyAllLibrariesPresent();
            return;
        }
        repo.connect(this);
        try {
            boolean reachable;
            try {
                log("Checking repository for reachability", Project.MSG_DEBUG);
                reachable = repo.checkRepositoryReachable();
            } catch (IOException e) {
                log(ERROR_REPO_PROBE_FAILED + e.getMessage(), Project.MSG_VERBOSE);
                reachable = false;
            }
            if (!reachable) {
                if (forceDownload) {
                    throw new BuildException(repo.toString() + " is unreachable and forceDownload is set");
                }
            } else {
                log("Repository is live", Project.MSG_DEBUG);
            }
            Iterator it = libraries.iterator();
            while (it.hasNext()) {
                Library library = (Library) it.next();
                library.bind(destDir);
                try {
                    if (repo.fetch(library)) {
                        fetched++;
                    }
                } catch (IOException e) {
                    log(ERROR_LIBRARY_FETCH_FAILED + library);
                    log(e.getMessage(), Project.MSG_VERBOSE);
                }
            }
        } finally {
            repo.disconnect();
        }
        if ((fetched < toFetch && forceDownload)) {
            throw new BuildException(ERROR_FORCED_DOWNLOAD_FAILED);
        }
        verifyAllLibrariesPresent();
    }

protected void bindAllLibraries() {
        Iterator it = libraries.iterator();
        while (it.hasNext()) {
            Library library = (Library) it.next();
            library.bind(destDir);
        }
    }
}

package org.apache.ivy.osgi.core;

import java.net.MalformedURLException;

import java.net.URI;

import java.net.URISyntaxException;

import java.net.URL;

import java.util.ArrayList;

import java.util.Date;

import java.util.HashMap;

