import java.util.List;

import java.util.Map;

import java.util.Map.Entry;

import java.util.Set;

import java.util.jar.Manifest;

import org.apache.ivy.Ivy;

import org.apache.ivy.core.module.descriptor.Artifact;

import org.apache.ivy.core.module.descriptor.Configuration;

import org.apache.ivy.core.module.descriptor.Configuration.Visibility;

import org.apache.ivy.core.module.descriptor.DefaultArtifact;

import org.apache.ivy.core.module.descriptor.DefaultDependencyDescriptor;

import org.apache.ivy.core.module.descriptor.DefaultExcludeRule;

import org.apache.ivy.core.module.descriptor.DefaultModuleDescriptor;

import org.apache.ivy.core.module.descriptor.ExtraInfoHolder;

import org.apache.ivy.core.module.id.ArtifactId;

import org.apache.ivy.core.module.id.ModuleId;

import org.apache.ivy.core.module.id.ModuleRevisionId;

import org.apache.ivy.osgi.util.Version;

import org.apache.ivy.osgi.util.VersionRange;

import org.apache.ivy.plugins.matcher.ExactOrRegexpPatternMatcher;

import org.apache.ivy.plugins.matcher.PatternMatcher;

import org.apache.ivy.plugins.parser.ModuleDescriptorParser;

public class BundleInfoAdapter {
public static final String CONF_NAME_DEFAULT = "default";

public static final Configuration CONF_DEFAULT = new Configuration(CONF_NAME_DEFAULT);

public static final String CONF_NAME_OPTIONAL = "optional";

public static final Configuration CONF_OPTIONAL = new Configuration(CONF_NAME_OPTIONAL, Visibility.PUBLIC, "Optional dependencies", new String[] { CONF_NAME_DEFAULT }, true, null);

public static final String CONF_NAME_TRANSITIVE_OPTIONAL = "transitive-optional";

public static final Configuration CONF_TRANSITIVE_OPTIONAL = new Configuration(CONF_NAME_TRANSITIVE_OPTIONAL, Visibility.PUBLIC, "Optional dependencies", new String[] { CONF_NAME_OPTIONAL }, true, null);

public static final String CONF_USE_PREFIX = "use_";

public static final String EXTRA_INFO_EXPORT_PREFIX = "_osgi_export_";

public static DefaultModuleDescriptor toModuleDescriptor(ModuleDescriptorParser parser, URI baseUri, BundleInfo bundle, ExecutionEnvironmentProfileProvider profileProvider) {
        return toModuleDescriptor(parser, baseUri, bundle, null, profileProvider);
    }

public static DefaultModuleDescriptor toModuleDescriptor(ModuleDescriptorParser parser, URI baseUri, BundleInfo bundle, Manifest manifest, ExecutionEnvironmentProfileProvider profileProvider) throws ProfileNotFoundException {
        DefaultModuleDescriptor md = new DefaultModuleDescriptor(parser, null);
        md.addExtraAttributeNamespace("o", Ivy.getIvyHomeURL() + "osgi");
        ModuleRevisionId mrid = asMrid(BundleInfo.BUNDLE_TYPE, bundle.getSymbolicName(), bundle.getVersion());
        md.setResolvedPublicationDate(new Date());
        md.setModuleRevisionId(mrid);
        md.addConfiguration(CONF_DEFAULT);
        md.addConfiguration(CONF_OPTIONAL);
        md.addConfiguration(CONF_TRANSITIVE_OPTIONAL);
        Set<String> exportedPkgNames = new HashSet<>(bundle.getExports().size());
        for (ExportPackage exportPackage : bundle.getExports()) {
            md.getExtraInfos().add(new ExtraInfoHolder(EXTRA_INFO_EXPORT_PREFIX + exportPackage.getName(), exportPackage.getVersion().toString()));
            exportedPkgNames.add(exportPackage.getName());
            String[] confDependencies = new String[exportPackage.getUses().size() + 1];
            int i = 0;
            for (String use : exportPackage.getUses()) {
                confDependencies[i++] = CONF_USE_PREFIX + use;
            }
            confDependencies[i] = CONF_NAME_DEFAULT;
            md.addConfiguration(new Configuration(CONF_USE_PREFIX + exportPackage.getName(), Visibility.PUBLIC, "Exported package " + exportPackage.getName(), confDependencies, true, null));
        }
        requirementAsDependency(md, bundle, exportedPkgNames);
        if (baseUri != null) {
            for (BundleArtifact bundleArtifact : bundle.getArtifacts()) {
                String type = "jar";
                String ext = "jar";
                String packaging = null;
                if (bundle.hasInnerClasspath() && !bundleArtifact.isSource()) {
                    packaging = "bundle";
                }
                if ("packed".equals(bundleArtifact.getFormat())) {
                    ext = "jar.pack.gz";
                    if (packaging != null) {
                        packaging += ",pack200";
                    } else {
                        packaging = "pack200";
                    }
                }
                if (bundleArtifact.isSource()) {
                    type = "source";
                }
                URI uri = bundleArtifact.getUri();
                if (uri != null) {
                    DefaultArtifact artifact = buildArtifact(mrid, baseUri, uri, type, ext, packaging);
                    md.addArtifact(CONF_NAME_DEFAULT, artifact);
                }
            }
        }
        if (profileProvider != null) {
            for (String env : bundle.getExecutionEnvironments()) {
                ExecutionEnvironmentProfile profile = profileProvider.getProfile(env);
                if (profile == null) {
                    throw new ProfileNotFoundException("Execution environment profile " + env + " not found");
                }
                for (String pkg : profile.getPkgNames()) {
                    ArtifactId id = new ArtifactId(ModuleId.newInstance(BundleInfo.PACKAGE_TYPE, pkg), PatternMatcher.ANY_EXPRESSION, PatternMatcher.ANY_EXPRESSION, PatternMatcher.ANY_EXPRESSION);
                    DefaultExcludeRule rule = new DefaultExcludeRule(id, ExactOrRegexpPatternMatcher.INSTANCE, null);
                    String[] confs = md.getConfigurationsNames();
                    for (String conf : confs) {
                        rule.addConfiguration(conf);
                    }
                    md.addExcludeRule(rule);
                }
            }
        }
        if (manifest != null) {
            for (Entry<Object, Object> entries : manifest.getMainAttributes().entrySet()) {
                md.addExtraInfo(new ExtraInfoHolder(entries.getKey().toString(), entries.getValue().toString()));
            }
        }
        return md;
    }

public static DefaultArtifact buildArtifact(ModuleRevisionId mrid, URI baseUri, URI uri, String type, String ext, String packaging) {
        DefaultArtifact artifact;
        if ("ivy".equals(uri.getScheme())) {
            artifact = decodeIvyURI(uri);
        } else {
            if (!uri.isAbsolute()) {
                uri = baseUri.resolve(uri);
            }
            Map<String, String> extraAtt = new HashMap<>();
            if (packaging != null) {
                extraAtt.put("packaging", packaging);
            }
            try {
                artifact = new DefaultArtifact(mrid, null, mrid.getName(), type, ext, new URL(uri.toString()), extraAtt);
            } catch (MalformedURLException e) {
                throw new RuntimeException("Unable to make the uri into the url", e);
            }
        }
        return artifact;
    }
}

package org.apache.tools.ant;

import java.util.ArrayList;

import java.util.Collections;

import java.util.Enumeration;

import java.util.Hashtable;

import java.util.Iterator;

import java.util.List;

import java.util.StringTokenizer;

import org.apache.tools.ant.property.LocalProperties;

public class Target implements TaskContainer {
private String name;

private String ifCondition = "";

private String unlessCondition = "";

private List dependencies = null;

private List children = new ArrayList();

private Location location = Location.UNKNOWN_LOCATION;

private Project project;

private String description = null;

public String toString() {
        return name;
    }

public void execute() throws BuildException {
        if (!testIfAllows()) {
            project.log(this, "Skipped because property '" + project.replaceProperties(ifCondition) + "' not set.", Project.MSG_VERBOSE);
            return;
        }
        if (!testUnlessAllows()) {
            project.log(this, "Skipped because property '" + project.replaceProperties(unlessCondition) + "' set.", Project.MSG_VERBOSE);
            return;
        }
        LocalProperties localProperties = LocalProperties.get(getProject());
        localProperties.enterScope();
        try {
            final int size = children.size();
            for (int i = 0; i < size; i++) {
                Object o = children.get(i);
                if (o instanceof Task) {
                    Task task = (Task) o;
                    task.perform();
                } else {
                    ((RuntimeConfigurable) o).maybeConfigure(project);
                }
            }
        } finally {
            localProperties.exitScope();
        }
    }

public final void performTasks() {
        RuntimeException thrown = null;
        project.fireTargetStarted(this);
        try {
            execute();
        } catch (RuntimeException exc) {
            thrown = exc;
            throw exc;
        } finally {
            project.fireTargetFinished(this, thrown);
        }
    }
}

